window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Konjunktiv II et phrases avec wenn · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"Si j'étais toi, je …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"La réalité d'Eva – les souhaits d'Eva. Complétez : würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"Elle aimerait pourtant être plus grande.","why":"*grösser sein* : la forme de souhait de *sein* est **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"Elle aimerait pourtant bien parler espagnol.","why":"Un infinitif se trouve à la fin (*sprechen*), donc le souhait se forme avec **würde** + infinitif.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"Elle préférerait pourtant travailler comme guide touristique.","why":"Infinitif à la fin (*arbeiten*) → **würde** + infinitif. *lieber* = plutôt.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"Elle aimerait pourtant avoir un grand appartement.","why":"*eine Wohnung haben* : la forme de souhait de *haben* est **hätte**. Pas besoin d'infinitif.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"À quoi pensent ces personnes ?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Associez chaque image à une expression de l'encadré.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"Si je ne devais pas travailler, je serais assis au jardin en ce moment.","why":"L'image 1 le montre en train de travailler, puis rêvant sur une chaise longue. Après une subordonnée en *wenn*, la principale commence par le verbe (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"Si j'avais une voiture, je ne devrais pas faire du vélo sous la pluie.","why":"Il fait du vélo sous la pluie ; une voiture lui éviterait cela. *müsste* est le Konjunktiv II de *müssen*. *Velo* est le mot suisse pour *Fahrrad*.","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"Si le bus n'avait pas de retard, je serais à l'heure au bureau.","why":"Un bus en retard la met en retard au travail. *wäre* est le Konjunktiv II de *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Réécrivez les phrases de a : commencez par la principale, puis la subordonnée en wenn.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"Je ne devrais pas faire du vélo sous la pluie si j'avais une voiture.","why":"D'abord la principale, puis la subordonnée en *wenn*. Dans la subordonnée en *wenn*, le verbe (*hätte*) va à la fin.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"Je serais à l'heure au bureau si le bus n'avait pas de retard.","why":"Même schéma : principale, virgule, *wenn* … verbe à la fin (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Complétez avec les mots de l'encadré. Chaque mot est utilisé une fois ; les mots barrés sont utilisés dans l'exemple.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"Je ferais certaines choses autrement si j'étais la cheffe de notre entreprise.","why":"*machen* à la fin → **würde** + infinitif. *Chefin sein* → **wäre**, à la fin de la subordonnée en *wenn*.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"Si j'étais Marco, je ferais absolument une formation professionnelle.","why":"*Marco sein* → **wäre** (comme *Wenn ich du wäre …*). La principale a l'infinitif *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"Si je pouvais décider librement, je travaillerais dans une petite entreprise.","why":"*frei entscheiden können* → **könnte** à la fin de la subordonnée en *wenn*. Principale avec *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"Si nous avions des enfants, je ne devrais travailler qu'à mi-temps.","why":"*Kinder haben* avec *wir* → **hätten**. L'encadré laisse **müsste** pour le dernier trou.","source":"k2","check":"*müsste* et *würde* sont tous deux corrects en b, c et e (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* est tout aussi bon). L'encadré indique seulement quels trois trous reçoivent *würde* et lequel reçoit *müsste* ; ce corrigé donne la répartition la plus probable. Demandez à votre enseignant ce que le livre attend."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"Je dois me dépêcher à cause de mon travail.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Réécrivez les réponses avec weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Parce que mon amie n'est pas ponctuelle.","why":"*wegen* + nom devient *weil* + une proposition avec un verbe ; le verbe (*ist*) va à la fin.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Parce qu'il fait mauvais.","why":"*des schlechten Wetters* → *das Wetter ist schlecht* ; après *weil*, le verbe va à la fin.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Parce que j'ai un rendez-vous important.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (accusatif après *haben*) ; verbe à la fin.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Complétez : wegen – weshalb – weil – deswegen – denn. Un mot peut être utilisé plusieurs fois.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"Je le comprends mal à cause de sa prononciation.","why":"Un nom suit (*seiner Aussprache*, génitif), pas une proposition → la préposition **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Un jour, j'aimerais bien aller en Italie, car j'aimerais voir la mer.","why":"Le verbe reste en 2e position après le trou (*ich möchte*) → **denn**. Avec *weil*, il irait à la fin.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"Je dois améliorer ma compréhension orale, c'est pourquoi je regarde beaucoup de films.","why":"La deuxième partie est la conséquence, et le verbe vient juste après le trou (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"Mes enfants ont vite appris l'allemand parce qu'à l'école enfantine, ils sont toujours avec des enfants suisses.","why":"Le verbe est à la fin (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"Pourquoi écris-tu les mots sur des petites cartes ?","why":"Il faut un mot interrogatif : **Weshalb** signifie *warum* (pourquoi)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"Ma sœur parle déjà presque couramment l'allemand, c'est pourquoi elle peut m'aider à apprendre l'allemand.","why":"Conséquence, et le verbe vient juste après le trou (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"Au cours de langue. Complétez : weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"Je n'ai pas pu faire le dernier exercice parce que je ne l'ai pas compris.","why":"Le verbe est à la fin (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"Il n'y avait personne à l'inscription. C'est pourquoi je suis rentré à la maison.","why":"Une nouvelle phrase qui donne la conséquence, avec le verbe juste après le trou (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"En raison de mes bonnes notes, je n'ai pas dû passer de test au début du cours.","why":"Un groupe nominal suit (*meiner guten Noten*, génitif pluriel) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"Il y a un cours de langue supplémentaire parce que de très nombreux participants se sont inscrits.","why":"Le verbe est à la fin (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Hier, je n'ai malheureusement pas pu venir au cours à cause de mon mal de dents.","why":"Un groupe nominal suit (*meiner Zahnschmerzen*, génitif pluriel) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"Qui trouve les meilleures excuses ? Choisissez une situation et écrivez. Les réponses modèles ne sont chaque fois qu'une possibilité parmi d'autres.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Malheureusement, je n'ai pas pu ranger la cuisine parce que j'ai soudain eu très mal au dos. J'ai dû m'allonger. C'est pourquoi j'ai regardé un film.","why":"Emploie *weil* (verbe à la fin : *hatte*) et *Deswegen* (verbe juste après : *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"À cause d'une grippe, je ne suis pas allé à l'examen final. J'avais beaucoup de fièvre, c'est pourquoi je suis resté au lit.","why":"Emploie *wegen* + génitif (*einer Grippe*) et *deswegen* + verbe (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"Je suis vraiment désolé ! Malheureusement, je suis arrivé en retard, car il y avait un accident sur l'autoroute. À cause de l'embouteillage, j'ai perdu deux heures.","why":"*denn* garde le verbe en 2e position (*war*). *wegen des Staus* : génitif de *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (phrases conditionnelles, y compris les irréelles au Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"grammis, dictionnaire des connecteurs : wenn (subordonnant, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"grammis, dictionnaire des connecteurs : weil (subordonnant, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis, dictionnaire des connecteurs : denn (causal, le verbe reste en 2e position)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis, dictionnaire des connecteurs : deswegen (conséquence ; se place devant le verbe ou au milieu)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen avec le génitif)","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"02-mehrere-sprachen","no":2,"title":"In mehreren Sprachen zu Hause","title_en":"Grandir avec plusieurs langues · lecture, message de forum, mots croisés, mots préférés","added":"2026-11-09","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 135","heading":"E  In mehreren Sprachen zu Hause","heading_en":"À la maison dans plusieurs langues","exercises":[{"no":"17","tag":"E2","instruction":"Zwei oder drei Sprachen in einer Familie – kein Problem?","instruction_en":"Deux ou trois langues dans une même famille – aucun problème ?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie die Namen.","part_instruction_en":"Qui dit quoi ? Lisez les trois textes et écrivez le nom de la personne qui dit chaque phrase.","reading":[{"label":"A · Amira, 33","text":"Ich denke, das ist manchmal schwierig, aber es geht. Bei uns ist das so: Ich bin Ägypterin und mein Deutsch ist noch nicht so gut, weil ich erst seit zwei Jahren in der Schweiz lebe. Mein Mann ist Schweizer. Wir haben uns in Ägypten kennengelernt, weil er dort sechs Jahre für eine Schweizer Firma gearbeitet hat. Jetzt leben wir seit fast zwei Jahren in Basel. Unsere Kinder sprechen sehr gut Arabisch und jetzt auch schon ziemlich gut Schweizerdeutsch. Mein Mann hat zwar in Ägypten mit ihnen Schweizerdeutsch gesprochen, aber er war ja nicht so viel zu Hause und in der Familie haben wir immer Arabisch gesprochen. Darum können das die Kinder viel besser. Manchmal verwenden sie auch zwei Sprachen in einem Satz. Wenn sie ein Wort nicht auf Schweizerdeutsch wissen, dann sagen sie einfach ein arabisches mitten im deutschen Satz. Aber ich finde das okay. Bald kommen sie in die Schule und dann werden sie sowieso besser Schweizerdeutsch als Arabisch sprechen."},{"label":"B · Janusz, 22","text":"Ich bin Pole, und als ich sechs Jahre alt war, sind wir in die Schweiz umgezogen. Meine Schwester und ich sind natürlich gleich in eine öffentliche Schule gegangen und konnten nach einem Jahr fliessend Hochdeutsch sprechen. Für meine Eltern war es schwieriger, denn meine Mutter war Hausfrau und hatte nicht so viel Kontakt zu Schweizern. Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet. Wir wollten nicht, dass unsere Eltern oder unsere Grossmutter mit uns Polnisch sprechen, wenn andere Kinder zu Besuch waren oder sie uns von der Schule abgeholt haben. Ich glaube, alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen. Natürlich ist mein Polnisch nicht so gut wie mein Deutsch, aber ich verstehe alles und kann auch ziemlich gut Alltagsgespräche führen. Das ist genug für mich und ich freue mich, dass ich mich mit unseren polnischen Verwandten unterhalten kann. Ich finde, man sollte daraus nicht so ein Problem machen."},{"label":"C · Yara, 18","text":"Ich komme aus Syrien. Ich bin mit drei Sprachen aufgewachsen, denn mein Vater hat für eine internationale Firma gearbeitet und wir haben auch einige Jahre in der Türkei und in Russland gelebt. Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch. Allerdings kann ich Arabisch am besten, weil wir in der Familie immer Arabisch gesprochen haben, egal in welchem Land wir waren. Jetzt leben wir in in der Schweiz und ich lerne seit zwei Jahren Deutsch. Das kann ich noch nicht so gut. Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf. Ich möchte Übersetzerin werden und so muss ich die Sprachen nicht mehr lernen. Das ist doch super, oder?"}],"items":[{"label":"1","text":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: ___","gaps":[["Janusz"]],"solution":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: **Janusz**","en":"«Les enfants veulent parler la même langue que leurs amis.» – Janusz","why":"Janusz (texte B) : *alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen.*"},{"label":"2","text":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: ___","gaps":[["Yara"]],"solution":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: **Yara**","en":"«C'est bien de parler plusieurs langues très bien, non ?» – Yara","why":"Yara (texte C) : *Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf.*"},{"label":"3","text":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: ___","gaps":[["Amira"]],"solution":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: **Amira**","en":"«Mes enfants passent d'une langue à l'autre.» – Amira","why":"Amira (texte A) : *Manchmal verwenden sie auch zwei Sprachen in einem Satz.* Elle est la seule à parler de ses propres enfants."}]},{"no":"17","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"Qu'est-ce qui est juste ? Relisez les textes. Tapez *richtig* (juste) ou *falsch* (faux) après chaque phrase ; dans le livre, vous cochez seulement les phrases justes.","items":[{"label":"1","text":"Amiras Kinder sprechen besser Arabisch als Deutsch. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Amiras Kinder sprechen besser Arabisch als Deutsch. → **richtig**","en":"Les enfants d'Amira parlent mieux l'arabe que l'allemand. → juste","why":"La famille parle toujours arabe à la maison : *Darum können das die Kinder viel besser.* (Leur allemand ici est du suisse allemand.)"},{"label":"2","text":"In Amiras Familie wird nur Deutsch gesprochen. → ___","gaps":[["falsch","f","nein"]],"solution":"In Amiras Familie wird nur Deutsch gesprochen. → **falsch**","en":"Dans la famille d'Amira, on ne parle qu'allemand. → faux","why":"Le contraire : *in der Familie haben wir immer Arabisch gesprochen.*"},{"label":"3","text":"Janusz hat sechs Jahre Deutsch gelernt. → ___","gaps":[["falsch","f","nein"]],"solution":"Janusz hat sechs Jahre Deutsch gelernt. → **falsch**","en":"Janusz a appris l'allemand pendant six ans. → faux","why":"Il avait six ans quand la famille a déménagé (*als ich sechs Jahre alt war*), et il parlait couramment le haut allemand après un an."},{"label":"4","text":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → **richtig**","en":"Janusz et sa sœur ne voulaient pas parler polonais avec leurs parents. → juste","why":"*Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet.*"},{"label":"5","text":"Yara spricht drei Sprachen fliessend. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Yara spricht drei Sprachen fliessend. → **richtig**","en":"Yara parle couramment trois langues. → juste","why":"*Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch.* L'allemand est sa quatrième langue, et elle ne le parle pas encore bien."},{"label":"6","text":"Yara lernt jetzt bald auch Deutsch. → ___","gaps":[["falsch","f","nein"]],"solution":"Yara lernt jetzt bald auch Deutsch. → **falsch**","en":"Yara va bientôt apprendre l'allemand aussi. → faux","why":"Elle ne commence pas bientôt (*bald*) : elle apprend déjà l'allemand depuis deux ans (*ich lerne seit zwei Jahren Deutsch*)."}]}]},{"page":"AB 136","heading":"E  In mehreren Sprachen zu Hause","heading_en":"À la maison dans plusieurs langues","exercises":[{"no":"18","tag":"E2 · Prüfung","instruction":"Einen Forumsbeitrag schreiben. Sie haben im Fernsehen eine Diskussionssendung zum Thema «Mehrsprachig aufwachsen» gesehen. Im Online-Forum der Sendung finden Sie folgende Meinung:","instruction_en":"Écrire un message de forum. Vous avez regardé un débat télévisé sur le fait de grandir avec plusieurs langues. Dans le forum en ligne de l'émission, vous trouvez cet avis :","reading":[{"label":"Online-Forum · 15.01. 16.55 Uhr · Sandra (52 Jahre)","text":"Also, ich kann den Gästen in Ihrer Sendung überhaupt nicht zustimmen. Ich finde, dass Kinder zuerst einmal eine Sprache richtig lernen sollen. Denn sonst können sie am Ende gar keine Sprache gut. Sie sprechen dann zwar zwei oder drei Sprachen ein bisschen, mischen sie aber und sprechen keine Sprache fliessend und auch keine wirklich gut."}],"part":"a","part_instruction":"Machen Sie Notizen.","part_instruction_en":"Prenez des notes sur les quatre questions. De courtes notes suffisent, pas de phrases complètes. Les notes modèles ne sont qu'une possibilité.","items":[{"label":"1","lead":"Kennen Sie eine Person, die mit zwei Sprachen aufwächst/aufgewachsen ist?","text":"","open":true,"solution":"Ja: der Sohn von meiner Nachbarin – Italienisch mit der Mutter, Schweizerdeutsch in der Schule","en":"Oui : le fils de ma voisine – italien avec sa mère, suisse allemand à l'école","why":"Notes seulement : un nom ou une personne, et quelles langues où."},{"label":"2","lead":"Was finden Sie gut?","text":"","open":true,"solution":"zwei Sprachen ohne Kurs lernen, Kontakt mit der Familie im Ausland, Vorteile im Beruf","en":"apprendre deux langues sans cours, contact avec la famille à l'étranger, avantages au travail","why":"Rassemblez deux ou trois avantages ; vous en avez besoin pour *Ich finde es sehr gut, dass …* en b."},{"label":"3","lead":"Was könnte schwierig sein?","text":"","open":true,"solution":"die Sprachen mischen, eine Sprache ist schwächer, viel Arbeit für die Eltern","en":"mélanger les langues, une langue est plus faible, beaucoup de travail pour les parents","why":"Ces notes vont dans *Es könnte schwierig sein, dass …* et *Auf der anderen Seite …* en b."},{"label":"4","lead":"Stimmen Sie Sandra zu?","text":"","open":true,"solution":"nein – Kinder lernen zwei Sprachen gut, wenn die Eltern viel mit ihnen sprechen","en":"non – les enfants apprennent bien deux langues si leurs parents leur parlent beaucoup","why":"Décidez oui ou non et donnez une raison : cela devient *Ich stimme Sandra (nicht) zu, denn …*."}]},{"no":"18","part":"b","part_instruction":"Schreiben Sie nun Ihre Meinung zum Thema (circa 80 Wörter).","part_instruction_en":"Écrivez maintenant votre opinion sur le sujet (environ 80 mots). Utilisez vos notes de a et quelques-unes des expressions.","phrases":["Ich denke, dass …","Ich finde es sehr gut/wichtig, dass …","Am allerwichtigsten ist … Deswegen/Daher/Aus diesem Grund …","Es könnte schwierig sein, dass …","Auf der anderen Seite …","Ich stimme Sandra (nicht) zu, denn …","**LERNTIPP** Sie brauchen diese Sätze, wenn Sie Ihre Meinung ausdrücken wollen. Wiederholen Sie sie möglichst oft."],"items":[{"label":"b","text":"","open":true,"solution":"Ich stimme Sandra nicht zu, **denn** viele Kinder lernen zwei Sprachen ohne Probleme. Der Sohn von meiner Nachbarin wächst mit Italienisch und Deutsch auf. Mit seiner Mutter spricht er Italienisch, in der Schule Schweizerdeutsch. Ich finde es sehr gut, dass er so früh zwei Sprachen lernt. Es könnte schwierig sein, dass er die Sprachen manchmal mischt. Auf der anderen Seite ist das bei kleinen Kindern normal. Am allerwichtigsten ist, dass die Eltern viel mit dem Kind sprechen. **Deswegen** sollte jeder Elternteil seine eigene Sprache sprechen.","en":"Je ne suis pas d'accord avec Sandra, car beaucoup d'enfants apprennent deux langues sans problèmes. Le fils de ma voisine grandit avec l'italien et l'allemand. Il parle italien avec sa mère et suisse allemand à l'école. Je trouve très bien qu'il apprenne deux langues si tôt. Le fait qu'il mélange parfois les langues pourrait être difficile. D'un autre côté, c'est normal chez les petits enfants. Le plus important de tout, c'est que les parents parlent beaucoup avec l'enfant. C'est pourquoi chaque parent devrait parler sa propre langue.","why":"Environ 85 mots, avec six des expressions. *denn* garde le verbe en 2e position (*lernen*) ; après *Deswegen*, le verbe vient tout de suite (*sollte*).","source":"deswegen"}]},{"no":"19","tag":"E3","instruction":"Lösen Sie das Rätsel.","instruction_en":"Résolvez les mots croisés. Chaque phrase donne la première lettre du mot manquant. La grille n'est pas affichée ici : tapez le mot en entier. Dans la grille du livre, Ä occupe une seule case.","items":[{"label":"a","lead":"Unser Heimatland ist Spanien. Wir s… aus Spanien.","text":"___","gaps":[["stammen"]],"solution":"**stammen**","en":"Notre pays d'origine est l'Espagne. Nous venons d'Espagne.","why":"*aus einem Land stammen* = venir d'un pays (comme *kommen aus*)."},{"label":"b","lead":"Jolanda und Mike sehen sich sechs Monate nicht. Das ist eine lange T… .","text":"___","gaps":[["Trennung"]],"solution":"**Trennung**","en":"Jolanda et Mike ne se voient pas pendant six mois. C'est une longue séparation.","why":"*die Trennung* = la séparation, le nom de *sich trennen*. *eine lange* → un nom féminin."},{"label":"c","lead":"Deutsch und Arabisch haben nicht die gleiche S… .","text":"___","gaps":[["Schrift"]],"solution":"**Schrift**","en":"L'allemand et l'arabe n'ont pas la même écriture.","why":"*die Schrift* = l'écriture, les lettres dans lesquelles une langue s'écrit. L'arabe utilise un autre alphabet."},{"label":"d","lead":"Peter lebt jetzt in Amerika. Seit er dort lebt, hat er sich stark v… .","text":"___","gaps":[["verändert"]],"solution":"**verändert**","en":"Peter vit maintenant en Amérique. Depuis qu'il y vit, il a beaucoup changé.","why":"*sich verändern* = changer (en parlant d'une personne). Perfekt : *hat sich verändert*. Le Ä occupe une seule case."},{"label":"e","lead":"Sie schreibt Bücher. Sie ist A… von Beruf.","text":"___","gaps":[["Autorin"]],"solution":"**Autorin**","en":"Elle écrit des livres. Elle est auteure de profession.","why":"*Sie* → la forme féminine en *-in* : *der Autor → die Autorin*. Pas d'article après *sein … von Beruf*."},{"label":"f","lead":"Die Kinder machen ihre Hausaufgaben nicht. Deshalb s… die Eltern mit ihnen.","text":"___","gaps":[["schimpfen"]],"solution":"**schimpfen**","en":"Les enfants ne font pas leurs devoirs. C'est pourquoi leurs parents les grondent.","why":"*mit jemandem schimpfen* = gronder quelqu'un. Sujet au pluriel *die Eltern* → *schimpfen*. Après *Deshalb*, le verbe vient tout de suite."},{"label":"g","lead":"Sie arbeitet erst seit wenigen Monaten. Sie hat noch wenig E… in ihrem Beruf.","text":"___","gaps":[["Erfahrung"]],"solution":"**Erfahrung**","en":"Elle ne travaille que depuis quelques mois. Elle a encore peu d'expérience dans son métier.","why":"*die Erfahrung* = l'expérience. *wenig Erfahrung haben* = avoir peu d'expérience."},{"label":"h","lead":"Jetzt haben wir ein Chaos. Alles ist d… .","text":"___","gaps":[["durcheinander"]],"solution":"**durcheinander**","en":"Maintenant, c'est le chaos. Tout est sens dessus dessous.","why":"*durcheinander sein* = être en désordre, mélangé. S'écrit en un seul mot."},{"label":"i","lead":"Für Ye-Jon tönen die Laute P und F gleich. Sie kann sie nicht u… .","text":"___","gaps":[["unterscheiden"]],"solution":"**unterscheiden**","en":"Pour Ye-Jon, les sons P et F se ressemblent. Elle ne peut pas les distinguer.","why":"*unterscheiden* = distinguer. Avec *kann*, l'infinitif va à la fin. *tönen* est le mot suisse pour *klingen* (sonner)."},{"label":"j","lead":"Ich reise in den Ferien nach Griechenland, aber leider kann ich kein G… .","text":"___","gaps":[["Griechisch"]],"solution":"**Griechisch**","en":"Je pars en Grèce pendant les vacances, mais malheureusement je ne parle pas du tout grec.","why":"*Griechisch* = la langue grecque, avec une majuscule. *kein Griechisch können* = ne pas parler du tout grec."},{"label":"k","lead":"Er isst nur Gemüse und Reis. Er isst a… Gemüse und Reis.","text":"___","gaps":[["ausschliesslich"]],"solution":"**ausschliesslich**","en":"Il ne mange que des légumes et du riz. Il mange exclusivement des légumes et du riz.","why":"*ausschliesslich* = exclusivement, rien d'autre que. Orthographe suisse avec *ss* ; en Allemagne, on l'écrit avec le s dur (Eszett)."},{"label":"★","lead":"Lösungswort (die markierte Zeile im Rätsel)","text":"___","gaps":[["Muttersprache"]],"solution":"**Muttersprache**","en":"Mot solution (la ligne en surbrillance dans la grille) : langue maternelle","why":"Chaque mot donne une lettre de la ligne en surbrillance : stam**M**en, trenn**U**ng, schrif**T**, (T dans la grille), veränd**E**rt, auto**R**in, (S dans la grille), schim**P**fen, erfah**R**ung, durchein**A**nder, unters**C**heiden, griec**H**isch, ausschli**E**sslich."}]}]},{"page":"AB 137","heading":"E  In mehreren Sprachen zu Hause","heading_en":"À la maison dans plusieurs langues","exercises":[{"no":"20","tag":"E3","instruction":"Mein schönstes deutsches Wort","instruction_en":"Mon plus beau mot allemand","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Associez chaque photo à un mot de l'encadré. Les points de couleur du livre indiquent l'article : bleu = der, vert = das, rouge = die.","box":["Sommervogel","Caramelchöpfli","Sternschnuppe"],"box_exact":true,"items":[{"label":"1","lead":"(Foto 1: ein Dessert mit Karamellsauce auf einem Teller)","text":"___","gaps":[["Caramelchöpfli","das Caramelchöpfli"]],"solution":"**Caramelchöpfli**","en":"das Caramelchöpfli – crème caramel (un dessert à la crème au caramel)","why":"Nom suisse de la crème caramel. *Chöpfli* signifie en suisse allemand ‘petite tête’ (*Kopf*). Point vert → *das*."},{"label":"2","lead":"(Foto 2: ein Stern mit einem langen, hellen Schweif am Nachthimmel)","text":"___","gaps":[["Sternschnuppe","die Sternschnuppe"]],"solution":"**Sternschnuppe**","en":"die Sternschnuppe – étoile filante","why":"*der Stern* = l'étoile ; *die Sternschnuppe* = l'étoile filante. Point rouge → *die*."},{"label":"3","lead":"(Foto 3: ein blauer Schmetterling auf einer orangen Blume)","text":"___","gaps":[["Sommervogel","der Sommervogel"]],"solution":"**Sommervogel**","en":"der Sommervogel – papillon","why":"Mot suisse pour *der Schmetterling* (papillon) ; le Duden le marque *schweizerisch, sonst landschaftlich*. Point bleu → *der*.","source":"sommervogel"}]},{"no":"20","part":"b","part_instruction":"Warum findet wohl jemand genau diese Wörter am schönsten? Was meinen Sie? Machen Sie Notizen und sprechen Sie.","part_instruction_en":"Pourquoi quelqu'un pourrait-il trouver justement ces mots les plus beaux ? Qu'en pensez-vous ? Prenez des notes, puis discutez-en. Les notes modèles ne sont qu'une possibilité.","example":[{"text":"Sommervogel: so farbig, …"}],"items":[{"label":"1","lead":"Sommervogel","text":"","open":true,"solution":"so farbig und leicht, erinnert an den Sommer, lustig: das Tier ist ja kein Vogel","en":"si coloré et léger, rappelle l'été, drôle : l'animal n'est pas du tout un oiseau","why":"Pensez à ce que le mot vous fait voir ou ressentir, et à sa sonorité."},{"label":"2","lead":"Caramelchöpfli","text":"","open":true,"solution":"süss, erinnert an die Kindheit, tönt lustig und typisch schweizerisch","en":"doux, rappelle l'enfance, sonne drôle et typiquement suisse","why":"*tönen* = mot suisse pour *klingen* (sonner)."},{"label":"3","lead":"Sternschnuppe","text":"","open":true,"solution":"romantisch, man kann sich etwas wünschen, tönt weich","en":"romantique, on peut faire un vœu, sonne doux","why":"De courtes notes suffisent : des adjectifs et une raison."}]},{"no":"21","tag":"E3","instruction":"Mein Lieblingswort","instruction_en":"Mon mot préféré","part":"a","part_instruction":"Welches deutsche Wort und welches Wort in Ihrer Muttersprache gefallen Ihnen? Warum? Schreiben Sie.","part_instruction_en":"Quel mot allemand et quel mot de votre langue maternelle aimez-vous ? Pourquoi ? Écrivez un court texte en utilisant les expressions. La réponse modèle n'est qu'une possibilité.","phrases":["Wenn ich … höre, dann denke ich an …","Deshalb finde ich …","Dieses Wort ist …","Das tönt …","Für mich ist …","Auf Deutsch/In meiner Muttersprache …"],"example":[{"text":"Wenn ich das Wort «Sommervogel» höre, dann denke ich an …"}],"items":[{"label":"a","text":"","open":true,"solution":"Mein deutsches Lieblingswort ist «gemütlich». **Wenn** ich dieses Wort höre, **dann** denke ich an einen Winterabend mit Tee, Kerzen und Freunden. **Deshalb** finde ich es so schön. Das tönt weich und warm. In meiner Muttersprache Englisch gibt es kein Wort mit genau dieser Bedeutung. Auf Englisch gefällt mir das Wort «sunshine». Für mich ist es ein fröhliches Wort, denn es tönt hell und freundlich.","en":"Mon mot allemand préféré est “gemütlich” (douillet, chaleureux). Quand j'entends ce mot, je pense à une soirée d'hiver avec du thé, des bougies et des amis. C'est pourquoi je le trouve si beau. Il sonne doux et chaud. Dans ma langue maternelle, l'anglais, il n'y a pas de mot avec exactement ce sens. En anglais, j'aime le mot “sunshine”. Pour moi, c'est un mot joyeux, parce qu'il sonne clair et aimable.","why":"*Wenn …, dann* + verbe tout de suite (*denke ich*) ; *Deshalb* + verbe tout de suite (*finde ich*). Remplacez par votre propre langue maternelle et vos propres mots.","source":"wenn"}]},{"no":"21","part":"b","part_instruction":"Präsentieren Sie Ihren Text im Kurs.","part_instruction_en":"Présentez votre texte en classe. Le modèle montre une façon possible de commencer.","items":[{"label":"b","text":"","open":true,"solution":"Ich möchte euch heute mein Lieblingswort vorstellen. Es ist das Wort «gemütlich». …","en":"Aujourd'hui, j'aimerais vous présenter mon mot préféré. C'est le mot “gemütlich”. …","why":"Commencez par nommer le mot, puis lisez votre texte de a. *euch* pour les camarades de classe, *Ihnen* si vous parlez de façon formelle."}]}]}],"sources":[{"id":"sommervogel","title":"Duden : Sommervogel (schweizerisch, sonst landschaftlich = Schmetterling)","url":"https://www.duden.de/rechtschreibung/Sommervogel"},{"id":"deswegen","title":"grammis, dictionnaire des connecteurs : deswegen (conséquence ; se place devant le verbe ou au milieu)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wenn","title":"grammis, dictionnaire des connecteurs : wenn (subordonnant, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"}]},{"id":"03-nachfragen-test","no":3,"title":"Nachfragen · Fremdsprachen lernen · Test Lektion 4","title_en":"Faire répéter poliment, apprendre des langues, chercher un emploi · Test de la leçon 4","added":"2026-11-10","book":"Schritte plus Neu 5 · Arbeitsbuch und Testheft · Lektion 4","sources":[{"id":"hueber","title":"Hueber : Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (corrigé officiel, Lektion 4)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (phrases conditionnelles, y compris les irréelles au Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"weil","title":"grammis, dictionnaire des connecteurs : weil (subordonnant, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis, dictionnaire des connecteurs : denn (causal, le verbe reste en 2e position)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis, dictionnaire des connecteurs : deswegen (conséquence ; se place devant le verbe ou au milieu)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"deshalb","title":"grammis, dictionnaire des connecteurs : deshalb (conséquence ; synonymes daher, deswegen)","url":"https://grammis.ids-mannheim.de/konnektoren/407094"},{"id":"darum","title":"grammis, dictionnaire des connecteurs : d(a)rum (conséquence)","url":"https://grammis.ids-mannheim.de/konnektoren/407096"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen avec le génitif)","url":"https://grammis.ids-mannheim.de/fragen/67"}],"pages":[{"page":"AB 133","heading":"C  Entschuldigung, könnten Sie das bitte wiederholen?","heading_en":"Excusez-moi, pourriez-vous répéter, s'il vous plaît ?","exercises":[{"no":"13","tag":"C2","instruction":"Ordnen Sie zu.","instruction_en":"Complétez chaque question ou phrase avec un début de l'encadré. Chaque début est utilisé une fois ; celui qui est barré est utilisé dans l'exemple.","box":["Tut mir leid, das Wort habe ich","Könnten Sie bitte langsamer","Entschuldigung, habe ich das","Könnten Sie das bitte","Darf ich Sie schnell","Was bedeutet","Könnten Sie mir vielleicht sagen","Wissen Sie, ob"],"box_used":[4],"box_exact":true,"example":[{"label":"a","text":"**Darf ich Sie schnell** etwas fragen?"}],"items":[{"label":"b","text":"___ der Ausdruck «es eilig haben»?","gaps":[["Was bedeutet"]],"solution":"**Was bedeutet** der Ausdruck «es eilig haben»?","en":"Que signifie l'expression « es eilig haben » ?","why":"*Was bedeutet …?* demande le sens d'un mot ou d'une expression. (*es eilig haben* = être pressé.)","source":"hueber"},{"label":"c","text":"___ sprechen?","gaps":[["Könnten Sie bitte langsamer"]],"solution":"**Könnten Sie bitte langsamer** sprechen?","en":"Pourriez-vous parler plus lentement, s'il vous plaît ?","why":"*Könnten Sie …* (Konjunktiv II) rend la demande polie ; l'infinitif *sprechen* va à la fin.","source":"hueber"},{"label":"d","text":"___ nicht verstanden.","gaps":[["Tut mir leid, das Wort habe ich"]],"solution":"**Tut mir leid, das Wort habe ich** nicht verstanden.","en":"Désolé, je n'ai pas compris ce mot.","why":"Perfekt : *habe … verstanden* ; *das Wort* est placé en tête pour insister, donc le verbe *habe* vient juste après.","source":"hueber"},{"label":"e","text":"Wie bitte? ___ wiederholen?","gaps":[["Könnten Sie das bitte"]],"solution":"Wie bitte? **Könnten Sie das bitte** wiederholen?","en":"Pardon ? Pourriez-vous répéter, s'il vous plaît ?","why":"Une demande polie avec *Könnten Sie …* ; *wiederholen* (répéter) va à la fin.","source":"hueber"},{"label":"f","text":"___ es hier auch Integrationskurse gibt?","gaps":[["Wissen Sie, ob"]],"solution":"**Wissen Sie, ob** es hier auch Integrationskurse gibt?","en":"Savez-vous s'il y a aussi des cours d'intégration ici ?","why":"*ob* introduit une question indirecte fermée (oui/non), donc le verbe *gibt* va à la fin.","source":"hueber"},{"label":"g","text":"___ richtig verstanden?","gaps":[["Entschuldigung, habe ich das"]],"solution":"**Entschuldigung, habe ich das** richtig verstanden?","en":"Excusez-moi, est-ce que j'ai bien compris ?","why":"Une question fermée (oui/non) au Perfekt : *habe* en premier, *verstanden* à la fin.","source":"hueber"},{"label":"h","text":"___, wo die Mensa ist?","gaps":[["Könnten Sie mir vielleicht sagen"]],"solution":"**Könnten Sie mir vielleicht sagen**, wo die Mensa ist?","en":"Pourriez-vous peut-être me dire où se trouve la cafétéria ?","why":"Une question indirecte avec *wo* : le verbe *ist* va à la fin. *die Mensa* = une cafétéria universitaire.","source":"hueber"}]},{"no":"14","tag":"C2","instruction":"Ergänzen Sie.","instruction_en":"Complétez les dialogues. Les premières lettres imprimées (et quelques lettres à l'intérieur des mots) sont données ; tapez les mots manquants en entier.","example":[{"label":"a","lead":"◆ Was ist denn das? ○ Das ist ein Zigerkrapfen. ◆ Entschuldigung, Zigerkrapfen kenne ich nicht.","text":"**Könnten Sie mir sagen**, was das ist?"}],"items":[{"label":"b","lead":"◆ Entschuldigen Sie bitte. Wo ist denn da die Mensa?  ○ Wie bitte? Das letzte Wort h… i… n… v… .  ◆ Die Mensa, die Uni-Kantine.","text":"Wie bitte? Das letzte Wort ___.","gaps":[["habe ich nicht verstanden"]],"solution":"Wie bitte? Das letzte Wort **habe ich nicht verstanden**.","en":"Pardon ? Je n'ai pas compris le dernier mot.","why":"Perfekt : *habe* en position 2 après *Das letzte Wort*, *verstanden* à la fin.","source":"hueber"},{"label":"c","lead":"◆ Also, dann treffen wir uns am 12.5. um 13.35 Uhr am Bahnhof.  ○ Entschuldigen Sie, es ist so laut da. K… S… den Termin b… w…?","text":"Entschuldigen Sie, es ist so laut da. ___ den Termin ___ ___?","gaps":[["Könnten Sie"],["bitte"],["wiederholen"]],"solution":"Entschuldigen Sie, es ist so laut da. **Könnten Sie** den Termin **bitte wiederholen**?","en":"Excusez-moi, il y a tellement de bruit ici. Pourriez-vous répéter l'heure du rendez-vous, s'il vous plaît ?","why":"Demande polie : *Könnten Sie* … infinitif *wiederholen* à la fin. *der Termin* = ici, l'heure du rendez-vous.","source":"hueber"},{"label":"d","lead":"◆ D… i… S… etwas f…?  ○ Ja, gern.  ◆ W… S…, o… es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","text":"◆ ___ etwas ___? ○ Ja, gern. ◆ ___, ___ es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","gaps":[["Darf ich Sie"],["fragen"],["Wissen Sie"],["ob"]],"solution":"◆ **Darf ich Sie** etwas **fragen**? ○ Ja, gern. ◆ **Wissen Sie**, **ob** es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","en":"Puis-je vous poser une question ? – Oui, bien sûr. – Savez-vous s'il y a aussi un bistro ou un restaurant dans le train de 14 h 33 pour Genève ?","why":"*Darf ich Sie etwas fragen?* ouvre poliment la conversation ; *ob* introduit une question indirecte fermée, donc *gibt* va à la fin.","source":"hueber"}]},{"no":"15","tag":"C2","instruction":"Bilden Sie Wörter und ordnen Sie zu.","instruction_en":"Formez des mots avec les syllabes de l'encadré et complétez les phrases. Les syllabes barrées (Men, sa) sont utilisées dans l'exemple.","phrases":["schrei · druck · ni · lung · ker · der · auf · Aus · ben · ho · Me · Wie · cha  (durchgestrichen im Beispiel: Men, sa)"],"example":[{"label":"a","text":"Ich wähle in der **Mensa** immer ein vegetarisches Gericht."}],"items":[{"label":"b","text":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten ___ geben? Diesmal will ich sie mir gleich in meinem Adressbuch ___, damit ich sie nicht wieder verliere.","gaps":[["Mechaniker"],["aufschreiben"]],"solution":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten **Mechaniker** geben? Diesmal will ich sie mir gleich in meinem Adressbuch **aufschreiben**, damit ich sie nicht wieder verliere.","en":"Ma voiture est de nouveau en panne. Pourrais-tu me redonner le numéro de téléphone de ton bon mécanicien, s'il te plaît ? Cette fois, je veux le noter tout de suite dans mon carnet d'adresses, pour ne pas le perdre à nouveau.","why":"Me-cha-ni-ker (une personne qui répare les voitures) et auf-schrei-ben (infinitif à la fin après *will*).","source":"hueber"},{"label":"c","text":"Was bedeutet der ___ «eine Entscheidung treffen»? Den habe ich noch nie gehört.","gaps":[["Ausdruck"]],"solution":"Was bedeutet der **Ausdruck** «eine Entscheidung treffen»? Den habe ich noch nie gehört.","en":"Que signifie l'expression « eine Entscheidung treffen » ? Je ne l'ai jamais entendue.","why":"Aus-druck : *der Ausdruck* = expression ; *der* et *Den* montrent que le mot est masculin. (*eine Entscheidung treffen* = prendre une décision.)","source":"hueber"},{"label":"d","text":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur ___.","gaps":[["Wiederholung"]],"solution":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur **Wiederholung**.","en":"Malheureusement, j'oublie souvent des mots allemands importants. J'ai besoin de plus de temps pour réviser.","why":"Wie-der-ho-lung : *zur* = *zu der*, donc un nom féminin suit : *die Wiederholung* (révision, répétition).","source":"hueber"}]}]},{"page":"AB 134","heading":"D  Fremdsprachen lernen – aber wie?","heading_en":"Apprendre des langues étrangères – mais comment ?","exercises":[{"no":"16","tag":"D1","instruction":"Fremdsprachen lernen – aber wie?","instruction_en":"Apprendre des langues étrangères – mais comment ?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ordnen Sie zu.","part_instruction_en":"Qui dit quoi ? Lisez les trois textes et écrivez la lettre du texte (A, B ou C) après chaque phrase.","reading":[{"label":"A  Mila, 17 Jahre","text":"Ich finde es total wichtig, dass man neue Wörter lernt und sie immer wieder wiederholt. Ich schreibe sie auf kleine Zettel oder Karten, auf der einen Seite das fremdsprachige Wort und auf der anderen die Übersetzung in meine Muttersprache. Diese Wortkarten habe ich immer in meiner Handtasche. Jeden Tag fahre ich eine Stunde mit dem Zug zur Schule. Das ist langweilig. Da habe ich viel Zeit und dann hole ich meine Wortkarten heraus und wiederhole die Wörter."},{"label":"B  Hakan, 19 Jahre","text":"Ich lerne seit vier Jahren Englisch in der Schule. Mir hilft es sehr, wenn ich viel Englisch höre. Ich habe viele MP3s mit Übungen aus dem Englischbuch und für die Aussprache auf meinem Smartphone. Ausserdem habe ich im Internet gute englische Podcasts gefunden. Die höre ich, wenn ich unterwegs bin. Ich möchte irgendwann nach der Schule ein Jahr nach London gehen und mir dort einen Job suchen. Darum will ich gut Englisch sprechen und auch meine Aussprache verbessern."},{"label":"C  Danila, 16 Jahre","text":"Ich bin vor drei Jahren in die Schweiz gekommen. Jetzt kann ich schon ziemlich gut Deutsch. Viel Zuhören ist für mich am allerwichtigsten. Deswegen habe ich im Bus, auf der Strasse, einfach überall immer den Schweizern zugehört und viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien. So habe ich viele Wörter und kleine Sätze der Alltagssprache gelernt, sogar auf Dialekt. Immer nur Grammatik und Wörter lernen, das finde ich uninteressant."}],"example":[{"label":"1","text":"Ich möchte meine Aussprache verbessern. → **B**"}],"items":[{"label":"2","text":"Ich höre oft anderen Leuten zu. → ___","gaps":[["C","Danila"]],"solution":"Ich höre oft anderen Leuten zu. → **C**","en":"J'écoute souvent les autres. → C (Danila)","why":"Danila : *Deswegen habe ich … einfach überall immer den Schweizern zugehört.*","source":"hueber"},{"label":"3","text":"Auf dem Weg zur Schule lerne ich Wörter. → ___","gaps":[["A","Mila"]],"solution":"Auf dem Weg zur Schule lerne ich Wörter. → **A**","en":"J'apprends des mots sur le chemin de l'école. → A (Mila)","why":"Mila sort ses fiches de vocabulaire pendant le trajet d'une heure en train jusqu'à l'école.","source":"hueber"},{"label":"4","text":"Ich möchte nach der Schule in England arbeiten. → ___","gaps":[["B","Hakan"]],"solution":"Ich möchte nach der Schule in England arbeiten. → **B**","en":"Après l'école, j'aimerais travailler en Angleterre. → B (Hakan)","why":"Hakan : *… ein Jahr nach London gehen und mir dort einen Job suchen.*","source":"hueber"},{"label":"5","text":"Ich schaue viel deutschsprachiges Fernsehen. → ___","gaps":[["C","Danila"]],"solution":"Ich schaue viel deutschsprachiges Fernsehen. → **C**","en":"Je regarde beaucoup la télévision en allemand. → C (Danila)","why":"Danila : *… viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien.*","source":"hueber"},{"label":"6","text":"Ich schreibe Wortkarten. → ___","gaps":[["A","Mila"]],"solution":"Ich schreibe Wortkarten. → **A**","en":"J'écris des fiches de vocabulaire. → A (Mila)","why":"Mila écrit le mot étranger d'un côté de la fiche et la traduction de l'autre.","source":"hueber"}]},{"no":"16","part":"b","part_instruction":"Schreiben Sie Sätze.","part_instruction_en":"Écrivez la deuxième phrase : commencez par le mot donné (Deshalb, Darum …) et utilisez les mots entre parenthèses. Le verbe vient juste après le mot de départ.","example":[{"label":"1","lead":"Mila möchte viele neue Wörter lernen. (neue Wörter auf Wortkarten schreiben)","text":"Deshalb **schreibt sie neue Wörter auf Wortkarten**."}],"items":[{"label":"2","lead":"Mila findet den Weg zur Schule langweilig. (mit Wortkarten neue Wörter wiederholen)","text":"","accept":["Darum wiederholt sie neue Wörter mit Wortkarten.","Darum wiederholt sie mit Wortkarten neue Wörter."],"solution":"**Darum wiederholt sie neue Wörter mit Wortkarten.**","en":"C'est pourquoi elle révise les nouveaux mots avec des fiches de vocabulaire.","why":"*Darum* occupe la position 1, donc le verbe conjugué *wiederholt* vient ensuite, puis le sujet *sie*.","source":"darum"},{"label":"3","lead":"Hakan hilft es, wenn er viel Englisch hört. (viele Podcasts auf seinem Smartphone haben)","text":"","accept":["Aus diesem Grund hat er viele Podcasts auf seinem Smartphone."],"solution":"**Aus diesem Grund hat er viele Podcasts auf seinem Smartphone.**","en":"Pour cette raison, il a beaucoup de podcasts sur son smartphone.","why":"*Aus diesem Grund* occupe la position 1, comme *deshalb* : le verbe *hat* vient ensuite, puis *er*.","source":"hueber"},{"label":"4","lead":"Hakan möchte nach der Schule ein Jahr in London arbeiten. (gut Englisch sprechen wollen)","text":"","accept":["Deswegen will er gut Englisch sprechen."],"solution":"**Deswegen will er gut Englisch sprechen.**","en":"C'est pour cela qu'il veut bien parler anglais.","why":"*Deswegen* + verbe de modalité *will* en position 2, infinitif *sprechen* à la fin.","source":"deswegen"},{"label":"5","lead":"Danila findet Grammatik und Wörter lernen uninteressant. (viel deutschsprachiges Fernsehen schauen)","text":"","accept":["Daher schaut sie viel deutschsprachiges Fernsehen."],"solution":"**Daher schaut sie viel deutschsprachiges Fernsehen.**","en":"Elle regarde donc beaucoup la télévision en allemand.","why":"*Daher* signifie la même chose que *deshalb* ; le verbe *schaut* vient juste après.","source":"deshalb"},{"label":"6","lead":"Für Danila ist Zuhören am allerwichtigsten. (einfach überall immer den Schweizern zugehört)","text":"","accept":["Aus diesem Grund hört sie einfach überall immer den Schweizern zu.","Aus diesem Grund hat sie einfach überall immer den Schweizern zugehört."],"solution":"**Aus diesem Grund hört sie einfach überall immer den Schweizern zu.**","en":"Pour cette raison, elle écoute tout simplement les Suisses, partout et tout le temps.","why":"*zuhören* est séparable : *hört … zu*. La consigne imprime *zugehört*, donc le Perfekt *hat … zugehört* (comme dans le texte de Danila) est aussi correct.","source":"hueber","check":"Le corrigé officiel donne le présent (*hört … zu*), bien que la consigne imprime le participe *zugehört*. Les deux phrases sont correctes en allemand ; demandez à votre enseignant ce que le livre attend."}]}]},{"page":"AB 138","heading":"Test Lektion 4","heading_en":"Test de la leçon 4","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Complétez le texte d'Arif. Le livre donne la première lettre et quelques lettres à l'intérieur de chaque mot ; tapez le mot en entier.","reading":[{"text":"Ich heisse Arif und bin 16 Jahre alt. Meine Familie und ich stammen (a) aus Syrien und unsere M… (b) ist Arabisch. Jetzt lerne ich seit einem Jahr Deutsch. Nächstes Jahr möchte ich eine Lehre beginnen. D… (c) möchte ich mein Deutsch verbessern. Natürlich spreche ich dann noch nicht f… (d) Deutsch. Besonders die Schrift und die A… (e) finde ich schwierig und ich verstehe auch noch nicht alle A… (f). Aber ich bin optimistisch."}],"example":[{"label":"a","text":"Meine Familie und ich **stammen** aus Syrien."}],"items":[{"label":"b","lead":"… und unsere M _ t _ _ _ s _ _ _ c _ _ ist Arabisch.","text":"… und unsere ___ ist Arabisch.","gaps":[["Muttersprache"]],"solution":"… und unsere **Muttersprache** ist Arabisch.","en":"… et notre langue maternelle est l'arabe.","why":"*die Muttersprache* = la première langue avec laquelle on grandit."},{"label":"c","lead":"D _ _ _ e _ e _ möchte ich mein Deutsch verbessern.","text":"___ möchte ich mein Deutsch verbessern.","gaps":[["Deswegen"]],"solution":"**Deswegen** möchte ich mein Deutsch verbessern.","en":"C'est pourquoi j'aimerais améliorer mon allemand.","why":"Les lettres données (D, e, e) correspondent à *Deswegen* ; il exprime la conséquence, et le verbe *möchte* suit juste après.","source":"deswegen"},{"label":"d","lead":"Natürlich spreche ich dann noch nicht f _ _ _ _ _ e _ _ Deutsch.","text":"Natürlich spreche ich dann noch nicht ___ Deutsch.","gaps":[["fliessend"]],"solution":"Natürlich spreche ich dann noch nicht **fliessend** Deutsch.","en":"Bien sûr, à ce moment-là, je ne parlerai pas encore couramment allemand.","why":"*fliessend* = couramment. Orthographe suisse avec *ss*."},{"label":"e","lead":"Besonders die Schrift und die A _ _ _ p _ _ _ _ e finde ich schwierig …","text":"Besonders die Schrift und die ___ finde ich schwierig …","gaps":[["Aussprache"]],"solution":"Besonders die Schrift und die **Aussprache** finde ich schwierig …","en":"Je trouve surtout l'écriture et la prononciation difficiles …","why":"*die Aussprache* = la prononciation (*aussprechen* = prononcer)."},{"label":"f","lead":"… und ich verstehe auch noch nicht alle A _ _ d _ _ c _ e.","text":"… und ich verstehe auch noch nicht alle ___.","gaps":[["Ausdrücke"]],"solution":"… und ich verstehe auch noch nicht alle **Ausdrücke**.","en":"… et je ne comprends pas encore toutes les expressions non plus.","why":"*der Ausdruck, die Ausdrücke* = expression(s) ; *alle* demande le pluriel."}]},{"no":"2","instruction":"Schreiben Sie Sätze mit wenn.","instruction_en":"Écrivez des phrases conditionnelles irréelles avec *wenn* et le Konjunktiv II (*wäre, hätte, könnte, müsste* ou *würde* + infinitif).","example":[{"label":"a","lead":"(ich heute nicht so viel vorhaben – spazieren gehen)","text":"Wenn **ich heute nicht so viel vorhätte, würde ich spazieren gehen**."}],"items":[{"label":"b","lead":"(ich mein Englisch besser sein – dir bei der Hausaufgabe helfen können)","text":"","accept":["Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.","Wenn mein Englisch besser wäre, würde ich dir bei der Hausaufgabe helfen können."],"solution":"**Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.**","en":"Si mon anglais était meilleur, je pourrais t'aider pour les devoirs.","why":"*sein* → **wäre** à la fin de la subordonnée en *wenn* ; *können* → **könnte**, puis la principale commence par le verbe.","source":"kond"},{"label":"c","lead":"(ich euch besser verstehen – ihr nicht durcheinander sprechen)","text":"","accept":["Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.","Ich würde euch besser verstehen, wenn ihr nicht durcheinandersprechen würdet.","Ich könnte euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet."],"solution":"**Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.**","en":"Je vous comprendrais mieux si vous ne parliez pas tous en même temps.","why":"D'abord la principale ; *würde* + infinitif dans les deux parties. Dans la subordonnée en *wenn*, *würdet* va à la fin.","source":"kond"},{"label":"d","lead":"(ich mehr Freizeit haben – nicht so viel arbeiten müssen)","text":"","accept":["Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste."],"solution":"**Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste.**","en":"J'aurais plus de temps libre si je ne devais pas autant travailler.","why":"*haben* → **hätte**, *müssen* → **müsste** (à la fin de la subordonnée en *wenn*).","source":"k2"}]},{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Complétez avec un mot de l'encadré. Chaque mot est utilisé une fois ; celui qui est barré est utilisé dans l'exemple (la réponse de l'item a).","box":["denn","Weshalb","Weil","Wegen","Deswegen"],"box_used":[2],"box_exact":true,"items":[{"label":"a","text":"___ möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","gaps":[["Weshalb"]],"solution":"**Weshalb** möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","en":"Pourquoi Costa veut-il devenir mécatronicien ? – Parce qu'il s'intéresse aux voitures.","why":"Il faut un mot interrogatif ; **Weshalb** = *warum* (pourquoi). La réponse imprimée commence par *Weil*.","source":"weil"},{"label":"b","text":"___ seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","gaps":[["Wegen"]],"solution":"**Wegen** seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","en":"Grâce à ses bonnes connaissances d'allemand, il a vite trouvé une place d'apprentissage.","why":"Un groupe nominal suit (*seiner guten Deutschkenntnisse*, génitif pluriel) → la préposition **Wegen**.","source":"wegen"},{"label":"c","text":"Er ist erst 17 Jahre alt. ___ wohnt er noch bei seinen Eltern.","gaps":[["Deswegen"]],"solution":"Er ist erst 17 Jahre alt. **Deswegen** wohnt er noch bei seinen Eltern.","en":"Il n'a que 17 ans. C'est pourquoi il habite encore chez ses parents.","why":"Une conséquence, et le verbe vient juste après le trou (*wohnt er*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Jetzt spart er Geld, ___ er möchte nach der Ausbildung eine eigene Wohnung haben.","gaps":[["denn"]],"solution":"Jetzt spart er Geld, **denn** er möchte nach der Ausbildung eine eigene Wohnung haben.","en":"Maintenant, il économise de l'argent, car il aimerait avoir son propre appartement après sa formation.","why":"Une cause, et le verbe reste en 2e position (*er möchte*) → **denn**.","source":"denn"}]},{"no":"4","instruction":"Wie kann man auch sagen? Ergänzen Sie.","instruction_en":"Comment le dire autrement ? Complétez la deuxième expression. Le livre donne quelques lettres ; tapez les mots en entier.","example":[{"label":"a","text":"Können Sie mir sagen, wo …? – **Wissen Sie**, wo …?"}],"items":[{"label":"b","lead":"Ich habe eine Frage. – D _ _ _  i _ _  S _ _  e _ _ _ _  f _ _ _ _ _?","text":"Ich habe eine Frage. – ___?","gaps":[["Darf ich Sie etwas fragen"]],"solution":"Ich habe eine Frage. – **Darf ich Sie etwas fragen**?","en":"J'ai une question. – Puis-je vous poser une question ?","why":"Une façon polie de commencer une question : *Darf ich Sie etwas fragen?*"},{"label":"c","lead":"Könnten Sie das bitte noch einmal sagen? – K _ _ _ t _ _  S _ _  d _ s  b _ _ t _  wi _ _ _ h _ _ _ _?","text":"Könnten Sie das bitte noch einmal sagen? – ___?","gaps":[["Könnten Sie das bitte wiederholen"]],"solution":"Könnten Sie das bitte noch einmal sagen? – **Könnten Sie das bitte wiederholen**?","en":"Pourriez-vous le redire, s'il vous plaît ? – Pourriez-vous répéter, s'il vous plaît ?","why":"*wiederholen* = répéter = *noch einmal sagen*."},{"label":"d","lead":"Was meinen Sie mit …? – W _ _  b _ _ e _ _ _ _ …?","text":"Was meinen Sie mit …? – ___ …?","gaps":[["Was bedeutet"]],"solution":"Was meinen Sie mit …? – **Was bedeutet** …?","en":"Que voulez-vous dire par … ? – Que signifie … ?","why":"*Was bedeutet …?* demande le sens, comme *Was meinen Sie mit …?*","check":"Les lettres de ce trou sont difficiles à lire sur la photo ; *Was bedeutet …?* leur correspond, et c'est l'expression de l'exercice 13. Demandez à votre enseignant si votre livre montre autre chose."},{"label":"e","lead":"Entschuldigung. – T _ _  m _ _  l _ _ _.","text":"Entschuldigung. – ___.","gaps":[["Tut mir leid"]],"solution":"Entschuldigung. – **Tut mir leid**.","en":"Excusez-moi. / Pardon. – Je suis désolé.","why":"*Tut mir leid* = je suis désolé, une autre façon de s'excuser."}]}]},{"page":"AB 139","heading":"Fokus Beruf: Stellensuche","heading_en":"Focus métier : chercher un emploi","exercises":[{"no":"1","instruction":"Yusuf sucht eine neue Stelle als Coiffeur. Er liest eine Broschüre mit Tipps für die Stellensuche. Lesen Sie die Tipps und ordnen Sie die Überschriften zu.","instruction_en":"Yusuf cherche un nouvel emploi de coiffeur. Il lit une brochure de conseils pour la recherche d'emploi. Lisez les conseils et écrivez la lettre du titre correspondant (A–E) après chaque paragraphe.","reading":[{"label":"1","text":"Machen Sie eine Liste von Personen, die Sie persönlich kennen: Bekannte, Kollegen, Freunde und Verwandte. Notieren Sie auch die Namen von früheren Arbeitgebern und Arbeitskollegen. Informieren Sie diese Personen – mündlich oder schriftlich – darüber, dass Sie auf Stellensuche sind. Wichtig: Informieren Sie Ihre Kontaktpersonen, wenn Sie eine Stelle gefunden haben."},{"label":"2","text":"Werden Sie aktiv. Warten Sie nicht, bis Sie ein passendes Stelleninserat finden, sondern schreiben Sie Ihre eigene Stellenanzeige. Suchen Sie ein Internet-Portal, das zu Ihrer Branche passt, und präsentieren Sie sich. Solche Annoncen kosten viel weniger als gedruckte Annoncen und Sie können sie ausserdem noch mit einer eigenen Bewerber-Website verbinden."},{"label":"3","text":"Erhöhen Sie Ihre Erfolgschancen mit einer Kurzbewerbung. Suchen Sie sich Ihre Wunschfirma und bewerben Sie sich. Dafür braucht es natürlich eine gute Recherche, damit Sie die «richtige» Firma und die «richtige» Person anschreiben. Wie ihr Name sagt, ist diese Bewerbung kurz: Sie besteht aus einem Bewerbungsschreiben und dem tabellarischen Lebenslauf."},{"label":"4","text":"Sind in Ihrer Branche Bewerbungen per Telefon üblich? Sind Sie besonders mutig und überzeugen vor allem mündlich sehr gut? Aus welchem Grund Sie sich für diese Bewerbungsform entscheiden: Wichtig ist auch hier eine gründliche Vorbereitung. Machen Sie Notizen und üben Sie das Gespräch mit Freunden. Fehlt Ihnen der Mut dazu, wählen Sie die schriftliche Bewerbung."},{"label":"5","text":"Die grösste Auswahl an Stelleninseraten finden Sie im Internet. Wichtig ist eine sorgfältige Analyse der Inserate: Was will die Firma? Welche Qualifikationen und Erfahrungen haben Sie? Machen Sie eine Liste und beantworten Sie diese Fragen. Können Sie ca. 80 Prozent der Anforderungen erfüllen, dann ist eine Bewerbung sinnvoll."}],"items":[{"label":"1","text":"Absatz 1 (Liste von Personen, die Sie kennen) → ___","gaps":[["C","C Das persönliche Netzwerk"]],"solution":"Absatz 1 (Liste von Personen, die Sie kennen) → **C**","en":"Paragraphe 1 (une liste de personnes que vous connaissez) → C, Votre réseau personnel","why":"Les amis, les collègues et les anciens employeurs forment votre réseau personnel.","source":"hueber"},{"label":"2","text":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → ___","gaps":[["A","A Online-Stellengesuch"]],"solution":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → **A**","en":"Paragraphe 2 (votre propre annonce sur Internet) → A, Annonce de recherche d'emploi en ligne","why":"*das Stellengesuch* = une annonce dans laquelle vous cherchez un emploi ; ici, sur un portail Internet.","source":"hueber"},{"label":"3","text":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → ___","gaps":[["E","E Spontanbewerbung"]],"solution":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → **E**","en":"Paragraphe 3 (une courte candidature auprès de l'entreprise de vos rêves) → E, Candidature spontanée","why":"Vous postulez auprès d'une entreprise qui n'a pas publié d'offre : *die Spontanbewerbung*.","source":"hueber"},{"label":"4","text":"Absatz 4 (Bewerbungen per Telefon) → ___","gaps":[["D","D Telefonische Bewerbung"]],"solution":"Absatz 4 (Bewerbungen per Telefon) → **D**","en":"Paragraphe 4 (postuler par téléphone) → D, Candidature par téléphone","why":"*per Telefon* = *telefonisch*.","source":"hueber"},{"label":"5","text":"Absatz 5 (Stelleninserate im Internet analysieren) → ___","gaps":[["B","B Stelleninserate"]],"solution":"Absatz 5 (Stelleninserate im Internet analysieren) → **B**","en":"Paragraphe 5 (analyser les offres d'emploi sur Internet) → B, Offres d'emploi","why":"*das Stelleninserat* (suisse) = une offre d'emploi publiée par une entreprise.","source":"hueber"}],"phrases":["A Online-Stellengesuch","B Stelleninserate","C Das persönliche Netzwerk","D Telefonische Bewerbung","E Spontanbewerbung"]},{"no":"2","instruction":"Yusuf hat entschieden, selbst aktiv zu werden, und hat ein Stellengesuch geschrieben. Lesen Sie seinen Text und unterstreichen Sie: – Wer und wie ist Yusuf? – Was kann er? – Was sucht er?","instruction_en":"Yusuf a décidé de prendre l'initiative et a rédigé une annonce de recherche d'emploi. Lisez son texte et trouvez qui est Yusuf et comment il est, ce qu'il sait faire et ce qu'il cherche. Écrivez les mots correspondants pour chaque question.","reading":[{"text":"Suchen Sie einen engagierten Coiffeur, der kreativ und flexibel ist? Dann rufen Sie mich, 24, an. Ich biete sechs Jahre Berufserfahrung und diverse Weiterbildungen im Bereich Stilberatung. Ich suche eine Herausforderung, bei der ich Neues lernen und mich weiter spezialisieren kann."}],"items":[{"label":"1","lead":"Wer und wie ist Yusuf?","text":"","open":true,"solution":"ein engagierter Coiffeur, kreativ und flexibel, 24 Jahre alt","en":"un coiffeur engagé, créatif et flexible, 24 ans","why":"Qui il est (métier, âge) et comment il est (adjectifs).","source":"hueber"},{"label":"2","lead":"Was kann er?","text":"","open":true,"solution":"sechs Jahre Berufserfahrung, diverse Weiterbildungen im Bereich Stilberatung","en":"six ans d'expérience professionnelle, diverses formations continues en conseil en style","why":"Ce qu'il offre : expérience et formation.","source":"hueber"},{"label":"3","lead":"Was sucht er?","text":"","open":true,"solution":"eine Herausforderung, bei der er Neues lernen und sich weiter spezialisieren kann","en":"un défi qui lui permette d'apprendre de nouvelles choses et de se spécialiser davantage","why":"La dernière phrase : *Ich suche …*","source":"hueber"}]},{"no":"3","instruction":"Ein Stellengesuch im Internet aufgeben. Sie suchen eine neue Stelle. Machen Sie eine Tabelle. Schreiben Sie dann einen Profiltext wie in 2.","instruction_en":"Publiez une annonce de recherche d'emploi sur Internet. Vous cherchez un nouvel emploi. Faites un tableau à trois colonnes (Qui suis-je et comment suis-je ? Que sais-je faire ? Qu'est-ce que je cherche ?), puis rédigez un profil comme celui de Yusuf en 2. La réponse modèle n'est qu'une possibilité.","phrases":["teamfähig/selbstständig/kontaktfreudig/zuverlässig/verantwortungsbewusst / … sein","gute Computer-/Sprachkenntnisse/Kenntnisse in … haben","gut mit … umgehen können","… Vollzeit/Teilzeit/auf Stundenbasis arbeiten","ab sofort / ab nächstem Monat / … suchen"],"example":[{"label":"Tabelle","text":"Wer und wie bin ich? flexibel, teamfähig, … | Was kann ich? … | Was suche ich? …"}],"items":[{"label":"1","lead":"Tabelle","text":"","open":true,"solution":"Wer und wie bin ich? flexibel, teamfähig, zuverlässig, kontaktfreudig | Was kann ich? gut mit Kunden umgehen, gute Computerkenntnisse, fliessend Deutsch und Englisch | Was suche ich? eine Teilzeitstelle ab nächstem Monat, ein internationales Team","en":"Qui suis-je et comment suis-je ? flexible, esprit d'équipe, fiable, sociable | Que sais-je faire ? bien m'occuper des clients, bonnes connaissances en informatique, allemand et anglais courants | Qu'est-ce que je cherche ? un emploi à temps partiel dès le mois prochain, une équipe internationale","why":"Quelques mots-clés par colonne suffisent ; utilisez les expressions de l'encadré.","source":"hueber"},{"label":"2","lead":"Profiltext","text":"","open":true,"solution":"Suchen Sie eine zuverlässige Verkäuferin, die teamfähig und kontaktfreudig ist? Ich kann gut mit Kunden umgehen, habe gute Computerkenntnisse und spreche fliessend Deutsch und Englisch. Ich suche ab nächstem Monat eine Teilzeitstelle in einem internationalen Team.","en":"Vous cherchez une vendeuse fiable, qui a l'esprit d'équipe et qui est sociable ? Je sais bien m'occuper des clients, j'ai de bonnes connaissances en informatique et je parle couramment allemand et anglais. Je cherche un emploi à temps partiel dans une équipe internationale dès le mois prochain.","why":"Les trois mêmes étapes que Yusuf : qui vous êtes, ce que vous savez faire, ce que vous cherchez. *die* dans la relative renvoie à *Verkäuferin*.","source":"hueber"}]}]},{"page":"Test L4 · 19","heading":"Grammatik","heading_en":"Grammaire","exercises":[{"no":"1","instruction":"Wunsch und Realität?","instruction_en":"Souhait et réalité ?","part":"a","part_instruction":"Ergänzen Sie.","part_instruction_en":"Nina doit faire une chose mais préférerait en faire une autre. Écrivez ce qu'elle préférerait faire avec *würde* + les mots entre parenthèses (avec *lieber*, ou *gern* à l'item 5).","example":[{"label":"1","lead":"Nina macht Diät. (Sahnetorte essen)","text":"Aber sie **würde lieber Sahnetorte essen**."}],"items":[{"label":"2","lead":"Nina muss für eine Sprachprüfung lernen. (Musik hören)","text":"Aber sie ___.","gaps":[["würde lieber Musik hören"]],"solution":"Aber sie **würde lieber Musik hören**.","en":"Mais elle préférerait écouter de la musique.","why":"*würde* en position 2, *lieber* = plutôt, infinitif *hören* à la fin.","source":"k2"},{"label":"3","lead":"Nina muss ihre Kleider aufräumen. (mit ihrer Freundin telefonieren)","text":"Aber sie ___.","gaps":[["würde lieber mit ihrer Freundin telefonieren"]],"solution":"Aber sie **würde lieber mit ihrer Freundin telefonieren**.","en":"Mais elle préférerait téléphoner à son amie.","why":"*würde* + *lieber* + infinitif à la fin.","source":"k2"},{"label":"4","lead":"Nina arbeitet am Computer. (Computerspiele spielen)","text":"Aber sie ___.","gaps":[["würde lieber Computerspiele spielen"]],"solution":"Aber sie **würde lieber Computerspiele spielen**.","en":"Mais elle préférerait jouer à des jeux vidéo.","why":"*würde* + *lieber* + infinitif à la fin.","source":"k2"},{"label":"5","lead":"Nina hat morgen sehr früh einen Termin. (bis spät in die Nacht lesen)","text":"Sie ___ gern ___.","gaps":[["würde aber"],["bis spät in die Nacht lesen"]],"solution":"Sie **würde aber** gern **bis spät in die Nacht lesen**.","en":"Mais elle aimerait bien lire jusque tard dans la nuit.","why":"Le livre imprime *gern* : *würde* + *gern* + infinitif (un souhait), avec *aber* après le verbe.","source":"k2"},{"label":"6","lead":"Nina verbringt den Abend mit ihren Eltern. (tanzen gehen)","text":"Aber sie ___.","gaps":[["würde lieber tanzen gehen"]],"solution":"Aber sie **würde lieber tanzen gehen**.","en":"Mais elle préférerait aller danser.","why":"*würde* + *lieber* ; les deux infinitifs *tanzen gehen* à la fin.","source":"k2"}]},{"no":"1","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Réécrivez les phrases de a sous forme de phrases conditionnelles irréelles : *Wenn Nina nicht …, würde sie …*","example":[{"label":"1","text":"Wenn Nina nicht Diät machen würde, würde sie Sahnetorte essen."}],"items":[{"label":"2","text":"","accept":["Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören."],"solution":"**Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören.**","en":"Si Nina ne devait pas réviser pour un examen de langue, elle écouterait de la musique.","why":"*muss* → **müsste** à la fin de la subordonnée en *wenn* ; la principale commence par *würde*.","source":"kond"},{"label":"3","text":"","accept":["Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.","Wenn Nina ihre Kleider nicht aufräumen müsste, würde sie mit ihrer Freundin telefonieren."],"solution":"**Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.**","en":"Si Nina ne devait pas ranger ses vêtements, elle téléphonerait à son amie.","why":"*müsste* + infinitif *aufräumen* : dans la subordonnée en *wenn*, *müsste* va en dernier.","source":"kond"},{"label":"4","text":"","accept":["Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.","Wenn Nina nicht am Computer arbeiten müsste, würde sie Computerspiele spielen."],"solution":"**Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.**","en":"Si Nina ne travaillait pas à l'ordinateur, elle jouerait à des jeux vidéo.","why":"Le corrigé accepte *arbeiten würde* ou *arbeiten müsste* dans la subordonnée en *wenn*."},{"label":"5","text":"","accept":["Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.","Wenn Nina morgen keinen Termin sehr früh hätte, würde sie bis spät in die Nacht lesen."],"solution":"**Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.**","en":"Si Nina n'avait pas un rendez-vous très tôt demain, elle lirait jusque tard dans la nuit.","why":"*hat* → **hätte**, à la fin de la subordonnée en *wenn*."},{"label":"6","text":"","accept":["Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.","Wenn Nina den Abend nicht mit ihren Eltern verbringen müsste, würde sie tanzen gehen."],"solution":"**Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.**","en":"Si Nina ne passait pas la soirée avec ses parents, elle irait danser.","why":"*würde* + infinitif dans les deux parties ; *verbringen würde* à la fin de la subordonnée en *wenn*."}]},{"no":"2","instruction":"Ergänzen Sie: darum – weil – wegen.","instruction_en":"Complétez avec *darum*, *weil* ou *wegen*. Chaque mot est utilisé deux fois.","box":["darum","weil","wegen"],"items":[{"label":"a","text":"Viele Deutsche hören Majids Grammatikfehler nicht, ___ er eine sehr gute Aussprache hat.","gaps":[["weil"]],"solution":"Viele Deutsche hören Majids Grammatikfehler nicht, **weil** er eine sehr gute Aussprache hat.","en":"Beaucoup d'Allemands ne remarquent pas les fautes de grammaire de Majid, parce qu'il a une très bonne prononciation.","why":"Une cause, et le verbe *hat* est à la fin → **weil**.","source":"weil"},{"label":"b","text":"Mirko hat die Prüfung nicht bestanden, ___ will er jetzt einen Intensivkurs machen.","gaps":[["darum"]],"solution":"Mirko hat die Prüfung nicht bestanden, **darum** will er jetzt einen Intensivkurs machen.","en":"Mirko n'a pas réussi l'examen, c'est pourquoi il veut maintenant suivre un cours intensif.","why":"Une conséquence, et le verbe *will* vient juste après le trou → **darum**.","source":"darum"},{"label":"c","text":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, ___ braucht er sehr gute Deutschkenntnisse.","gaps":[["darum"]],"solution":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, **darum** braucht er sehr gute Deutschkenntnisse.","en":"Hassan veut travailler comme médecin dans un hôpital allemand, c'est pourquoi il a besoin de très bonnes connaissances d'allemand.","why":"Conséquence + verbe juste après le trou (*braucht er*) → **darum**.","source":"darum"},{"label":"d","text":"Camilla ist Managerin und kann ___ ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","gaps":[["wegen"]],"solution":"Camilla ist Managerin und kann **wegen** ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","en":"Camilla est manager et ne peut pas suivre régulièrement le cours d'allemand à cause de ses nombreuses conférences.","why":"Un groupe nominal suit (*ihrer vielen Konferenzen*, génitif pluriel) → **wegen**.","source":"wegen"},{"label":"e","text":"Boris wird ___ seines Akzents sofort als Russe erkannt.","gaps":[["wegen"]],"solution":"Boris wird **wegen** seines Akzents sofort als Russe erkannt.","en":"Boris est tout de suite reconnu comme Russe à cause de son accent.","why":"Groupe nominal au génitif (*seines Akzents*) → **wegen**.","source":"wegen"},{"label":"f","text":"Anja würde gern Arabisch lernen, ___ sie die arabische Schrift so schön findet.","gaps":[["weil"]],"solution":"Anja würde gern Arabisch lernen, **weil** sie die arabische Schrift so schön findet.","en":"Anja aimerait apprendre l'arabe, parce qu'elle trouve l'écriture arabe si belle.","why":"Une cause, avec le verbe *findet* à la fin → **weil**.","source":"weil"}]}]},{"page":"Test L4 · 20","heading":"Wortschatz","heading_en":"Vocabulaire","exercises":[{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Complétez le texte de Ferdez avec les mots de l'encadré. Chaque mot est utilisé une fois ; celui qui est barré est utilisé dans l'exemple. La fiche suit l'orthographe d'Allemagne avec l'eszett ; ici, orthographe suisse avec *ss* (*fliessend*).","box":["Akzent","fliessend","schimpfe","Muttersprache","Schrift","übersetzen","vergleiche"],"box_used":[3],"box_exact":true,"example":[{"label":"a","text":"Mein Name ist Ferdez. Ich komme aus Mazedonien. Meine **Muttersprache** ist Albanisch, aber ich spreche auch Mazedonisch."}],"items":[{"label":"b","text":"Im Mazedonischen wird die kyrillische ___ verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","gaps":[["Schrift"]],"solution":"Im Mazedonischen wird die kyrillische **Schrift** verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","en":"En macédonien, on utilise l'alphabet cyrillique. C'est pourquoi, au début, il n'était pas facile pour moi d'écrire en allemand.","why":"*die kyrillische Schrift* = l'alphabet cyrillique."},{"label":"c","text":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich ___ Deutsch, finde ich.","gaps":[["fliessend"]],"solution":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich **fliessend** Deutsch, finde ich.","en":"Je vis en Bavière depuis huit ans. Aujourd'hui, je parle couramment allemand, je trouve.","why":"*fliessend Deutsch sprechen* = parler couramment allemand."},{"label":"d","text":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen ___ habe!","gaps":[["Akzent"]],"solution":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen **Akzent** habe!","en":"Mais mes collègues du nord de l'Allemagne disent que j'ai un accent bavarois !","why":"*einen … Akzent haben* = avoir un accent ; *einen bayerischen* → nom masculin."},{"label":"e","text":"Wenn ich auf Bayerisch ___, lachen meine Kollegen sich kaputt.","gaps":[["schimpfe"]],"solution":"Wenn ich auf Bayerisch **schimpfe**, lachen meine Kollegen sich kaputt.","en":"Quand je rouspète en bavarois, mes collègues sont pliés de rire.","why":"*schimpfen* = rouspéter, jurer ; *ich schimpfe* à la fin de la subordonnée en *wenn*."},{"label":"f","text":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander ___, dann fällt mir auf, …","gaps":[["vergleiche"]],"solution":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander **vergleiche**, dann fällt mir auf, …","en":"Quand je compare l'allemand, le macédonien et l'albanais entre eux, je remarque …","why":"*miteinander vergleichen* = comparer entre eux ; *ich vergleiche* à la fin de la subordonnée en *wenn*."},{"label":"g","text":"… dass man nicht alle Wörter wirklich gut in die andere Sprache ___ kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","gaps":[["übersetzen"]],"solution":"… dass man nicht alle Wörter wirklich gut in die andere Sprache **übersetzen** kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","en":"… qu'on ne peut pas vraiment bien traduire tous les mots dans l'autre langue. Aujourd'hui, je me sens chez moi en Macédoine et en Allemagne.","why":"*in eine Sprache übersetzen* = traduire dans une langue ; l'infinitif se place avant *kann*, à la fin de la subordonnée en *dass*."}]},{"no":"Pause","instruction":"Was bedeutet das? Kreuzen Sie an. «Lügen haben kurze Beine.»","instruction_en":"Que signifie le proverbe « Lügen haben kurze Beine » (les mensonges ont les jambes courtes) ? Tapez A ou B.","items":[{"label":"A/B","lead":"A Die Wahrheit kommt immer schnell ans Licht. Darum sollte man nicht lügen.  B Wer lügt, der bekommt zur Strafe kurze Beine.","text":"___","gaps":[["A"]],"solution":"**A**","en":"A : La vérité éclate toujours vite. C'est pourquoi il ne faut pas mentir.","why":"Un mensonge ne va pas loin, comme quelqu'un qui a les jambes courtes : il est vite découvert. B joue sur le sens littéral des mots."}]},{"no":"4","instruction":"Welches Wort passt auch? Notieren Sie.","instruction_en":"Quel mot de l'encadré pourrait remplacer le mot souligné ? Écrivez-le. Chaque mot est utilisé une fois ; celui qui est barré est utilisé dans l'exemple. Les mots soulignés sont affichés en gras.","box":["allerdings","allmählich","aufschreiben","deswegen","ebenso","irgendwann","korrekt","stammt"],"box_used":[7],"box_exact":true,"example":[{"label":"a","text":"Meine Familie **kommt** aus Iran. → stammt"}],"items":[{"label":"b","lead":"Ich selbst bin **aber** in Mainz geboren.","text":"___","gaps":[["allerdings"]],"solution":"**allerdings**","en":"Moi, en revanche, je suis né à Mayence.","why":"*allerdings* = *aber* : il nuance ce qui a été dit avant."},{"label":"c","lead":"Mit mir haben meine Eltern immer Deutsch gesprochen, **deshalb** kann ich leider nicht Farsi.","text":"___","gaps":[["deswegen"]],"solution":"**deswegen**","en":"Mes parents ont toujours parlé allemand avec moi, c'est pourquoi je ne sais malheureusement pas parler farsi.","why":"*deswegen* = *deshalb* (conséquence, le verbe suit juste après).","source":"deswegen"},{"label":"d","lead":"Jetzt nehme ich an einem Sprachkurs teil. Ich finde, Farsi ist **genauso** schwierig wie Deutsch.","text":"___","gaps":[["ebenso"]],"solution":"**ebenso**","en":"Maintenant, je suis un cours de langue. Je trouve le farsi tout aussi difficile que l'allemand.","why":"*ebenso … wie* = *genauso … wie* = tout aussi … que."},{"label":"e","lead":"Besonders die Schrift! Ich bin ein Mensch, der sich alle neuen Wörter **notieren** muss.","text":"___","gaps":[["aufschreiben"]],"solution":"**aufschreiben**","en":"Surtout l'écriture ! Je suis quelqu'un qui doit noter tous les nouveaux mots.","why":"*sich etwas notieren* = *sich etwas aufschreiben* = noter quelque chose."},{"label":"f","lead":"Das ist schwierig, wenn man es in einer Schrift tun muss, die man auch erst **langsam** lernt.","text":"___","gaps":[["allmählich"]],"solution":"**allmählich**","en":"C'est difficile quand on doit le faire dans une écriture qu'on n'apprend que peu à peu.","why":"*allmählich* = lentement, pas à pas, peu à peu."},{"label":"g","lead":"Auch die Aussprache ist nicht leicht. Es gibt da diesen Laut «gh», den kann ich nicht **richtig** aussprechen.","text":"___","gaps":[["korrekt"]],"solution":"**korrekt**","en":"La prononciation n'est pas facile non plus. Il y a ce son « gh » que je n'arrive pas à prononcer correctement.","why":"*korrekt* = *richtig* = correctement."},{"label":"h","lead":"**Eines Tages** klappt es – hoffe ich jedenfalls!","text":"___","gaps":[["irgendwann","Irgendwann"]],"solution":"**irgendwann**","en":"Un jour, ça marchera – du moins je l'espère !","why":"*irgendwann* = à un moment donné, un jour = *eines Tages*."}]}]},{"page":"Test L4 · 21","heading":"Lesen","heading_en":"Lecture","exercises":[{"no":"5","instruction":"Lesen Sie und kreuzen Sie an: Was ist richtig?","instruction_en":"Lisez les réponses au sondage « Est-ce important d'apprendre l'allemand ? » et choisissez la bonne fin pour chaque phrase. Tapez la fin (ou seulement ses premiers mots).","reading":[{"label":"Brad, 30, aus Australien","text":"«Meine Freundin ist Deutsche. Deshalb bin ich vor einem Jahr nach Deutschland gekommen. Ich dachte, dass ich mit Englisch als Muttersprache keine Schwierigkeiten haben würde, einen Job zu finden. Aber immer wenn ich mich bewarb, bekam ich zur Antwort: Lernen Sie erst einmal richtig Deutsch. Dann können Sie wiederkommen. Offenbar glauben die Leute, dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht. Seit sechs Monaten besuche ich nun einen Deutschkurs.»"},{"label":"Alena, 24, aus Tschechien","text":"«Meine Grossmutter hat 30 Jahre in Wien gelebt. Ich habe sie als Kind oft besucht und Wien dabei sehr gut kennengelernt. Ich denke, ich habe in Wien bessere Karrierechancen als bei uns zu Hause. Darum habe ich jetzt das Zertifikat Deutsch gemacht. Mit dem Zertifikat habe ich bestimmt gute Chancen, wenn ich mich bei österreichischen Firmen bewerbe.»"},{"label":"Ewa, 23, aus Polen","text":"«Ich finde es aus historischen Gründen wichtig, Deutsch zu lernen. Denn Polen und Deutschland verbindet eine lange Geschichte, die nicht immer schön war. Aber gerade deshalb ist es wichtig, dass wir uns gegenseitig gut kennenlernen. Ich würde mir wünschen, dass auch mehr Deutsche sich für die polnische Sprache interessieren würden.»"},{"label":"Sopha, 32, aus Thailand","text":"«Mein Mann stammt aus Hessen. Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche. Aber jetzt gehen unsere beiden Söhne zur Schule, und ich habe gemerkt, dass meine Deutschkenntnisse nicht mehr ausreichend sind: In der Kommunikation mit der Klassenlehrerin und bei Elternabenden habe ich grosse Schwierigkeiten. Deshalb nehme ich jetzt an einem Deutschkurs für Eltern teil.»"},{"label":"Abdullah, 35, aus Bahrain","text":"«Ich arbeite seit ein paar Monaten an einer deutschen Klinik als Arzt. Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen. Im Krankenhaus brauche ich eigentlich gar nicht so viel Deutsch, denn für die Gespräche mit den Patienten genügt mein Deutsch, und die Kollegen sprechen alle sehr gut Englisch. Aber natürlich möchte ich die Sprache des Landes gut können, in dem ich lebe. Dann versteht man die Menschen und ihr Land besser. Aus diesem Grund lerne ich weiter Deutsch.»"},{"label":"Zeliha, 45, aus der Türkei","text":"«Ich bin nach Dortmund gekommen, als ich meinen Mann – einen Deutschtürken – geheiratet habe. Schnell kamen vier Kinder zur Welt. Das Geld war immer knapp bei uns, deswegen habe ich neben dem Haushalt und der Kindererziehung Schicht gearbeitet. Für einen Deutschkurs war nie Zeit und Geld da. Meine Kinder haben oft geschimpft, weil ich so schlecht Deutsch sprach. Jetzt lerne ich endlich richtig Deutsch, und meine Kinder helfen mir beim Lernen.»"}],"items":[{"label":"a","lead":"Wer gut Englisch kann, … ○ findet in Deutschland problemlos einen Job. ○ muss trotzdem gut Deutsch lernen.","text":"Wer gut Englisch kann, ___.","gaps":[["muss trotzdem gut Deutsch lernen","muss trotzdem"]],"solution":"Wer gut Englisch kann, **muss trotzdem gut Deutsch lernen**.","en":"Celui qui parle bien anglais doit quand même bien apprendre l'allemand.","why":"Brad, dont la langue maternelle est l'anglais, s'entendait dire sans cesse : *Lernen Sie erst einmal richtig Deutsch.*"},{"label":"b","lead":"Deutsche glauben offenbar, … ○ dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat. ○ dass man für eine Ausbildung Deutsch braucht.","text":"Deutsche glauben offenbar, ___.","gaps":[["dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat","dass man ohne perfektes Deutsch"]],"solution":"Deutsche glauben offenbar, **dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat**.","en":"Les Allemands croient apparemment que, sans un allemand parfait, on n'a pas de compétences professionnelles.","why":"Brad : *… dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht.*"},{"label":"c","lead":"Alena hofft, dass sie mit dem Zertifikat Deutsch … ○ eine Arbeitsstelle in Österreich findet. ○ besser Bewerbungen schreiben kann.","text":"Alena hofft, dass sie mit dem Zertifikat Deutsch ___.","gaps":[["eine Arbeitsstelle in Österreich findet","eine Arbeitsstelle"]],"solution":"Alena hofft, dass sie mit dem Zertifikat Deutsch **eine Arbeitsstelle in Österreich findet**.","en":"Alena espère trouver un emploi en Autriche grâce au certificat d'allemand.","why":"Alena compte sur de bonnes chances *bei österreichischen Firmen*."},{"label":"d","lead":"Als Polin will Ewa Deutsch können, denn … ○ Deutschland und Polen haben eine gemeinsame Geschichte. ○ sie hat viele Deutsche kennengelernt.","text":"Als Polin will Ewa Deutsch können, denn ___.","gaps":[["Deutschland und Polen haben eine gemeinsame Geschichte","Deutschland und Polen"]],"solution":"Als Polin will Ewa Deutsch können, denn **Deutschland und Polen haben eine gemeinsame Geschichte**.","en":"En tant que Polonaise, Ewa veut savoir l'allemand, car l'Allemagne et la Pologne ont une histoire commune.","why":"Ewa : *Denn Polen und Deutschland verbindet eine lange Geschichte.*"},{"label":"e","lead":"Ewa findet es … ○ toll, dass so viel Deutsche Polnisch sprechen. ○ schade, dass sich nicht so viele Deutsche für Polnisch interessieren.","text":"Ewa findet es ___.","gaps":[["schade, dass sich nicht so viele Deutsche für Polnisch interessieren","schade"]],"solution":"Ewa findet es **schade, dass sich nicht so viele Deutsche für Polnisch interessieren**.","en":"Ewa trouve dommage que peu d'Allemands s'intéressent au polonais.","why":"Ewa aimerait que davantage d'Allemands s'intéressent au polonais."},{"label":"f","lead":"Sopha hat … ○ von ihrem Mann Deutsch gelernt. ○ hat einen Integrationskurs besucht.","text":"Sopha hat ___.","gaps":[["von ihrem Mann Deutsch gelernt","von ihrem Mann"]],"solution":"Sopha hat **von ihrem Mann Deutsch gelernt**.","en":"Sopha a appris l'allemand avec son mari.","why":"Sopha : *Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche.*"},{"label":"g","lead":"Sie … ○ muss ihren Söhnen bei den Deutschhausaufgaben helfen. ○ hat Probleme, weil sie die Lehrer nicht gut genug versteht.","text":"Sie ___.","gaps":[["hat Probleme, weil sie die Lehrer nicht gut genug versteht","hat Probleme"]],"solution":"Sie **hat Probleme, weil sie die Lehrer nicht gut genug versteht**.","en":"Elle a des problèmes parce qu'elle ne comprend pas assez bien les enseignants.","why":"Avec l'enseignant de classe et aux soirées de parents, elle a *grosse Schwierigkeiten*."},{"label":"h","lead":"Für die Arbeitserlaubnis … ○ werden gute Deutschkenntnisse erwartet. ○ braucht man gar nicht so gute Deutschkenntnisse.","text":"Für die Arbeitserlaubnis ___.","gaps":[["werden gute Deutschkenntnisse erwartet","werden gute"]],"solution":"Für die Arbeitserlaubnis **werden gute Deutschkenntnisse erwartet**.","en":"Pour le permis de travail, on attend de bonnes connaissances d'allemand.","why":"Abdullah : *Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen.*"},{"label":"i","lead":"Abdullah will gut Deutsch können, weil … ○ die Patienten nicht Englisch sprechen. ○ er in Deutschland lebt.","text":"Abdullah will gut Deutsch können, weil ___.","gaps":[["er in Deutschland lebt"]],"solution":"Abdullah will gut Deutsch können, weil **er in Deutschland lebt**.","en":"Abdullah veut bien savoir l'allemand parce qu'il vit en Allemagne.","why":"Il veut connaître la langue *des Landes …, in dem ich lebe* ; son allemand suffit déjà pour les patients."},{"label":"j","lead":"Zeliha lernt Deutsch … ○ , weil sie Geld verdienen muss. ○ wegen ihrer Kinder.","text":"Zeliha lernt Deutsch ___.","gaps":[["wegen ihrer Kinder"]],"solution":"Zeliha lernt Deutsch **wegen ihrer Kinder**.","en":"Zeliha apprend l'allemand à cause de ses enfants.","why":"Ses enfants se plaignaient que son allemand soit si mauvais, et maintenant ils l'aident à apprendre."}]}]},{"page":"Test L4 · 22","heading":"Sprechen","heading_en":"Expression orale","exercises":[{"no":"7","instruction":"Welche Reaktion passt am besten? Verbinden Sie.","instruction_en":"Quelle réponse convient le mieux ? Écrivez le numéro de la réponse (1–6) après chaque phrase. (L'exercice 6 de cette page est une compréhension orale et n'est pas repris.)","example":[{"label":"a","text":"Darf ich Sie kurz etwas fragen? → **2** Natürlich, gern."}],"items":[{"label":"b","text":"Mein Name ist Kranitzky-Krampe. → ___","gaps":[["5"]],"solution":"Mein Name ist Kranitzky-Krampe. → **5**","en":"Je m'appelle Kranitzky-Krampe. → 5 Pardon, quel est votre nom, déjà ?","why":"Un nom long et inhabituel : vous redemandez."},{"label":"c","text":"Zu Kleidung kann man auch «Klamotten» sagen. → ___","gaps":[["4"]],"solution":"Zu Kleidung kann man auch «Klamotten» sagen. → **4**","en":"Pour « vêtements », on peut aussi dire « Klamotten ». → 4 Je n'ai jamais entendu ce mot.","why":"Un mot nouveau (familier) : *Das Wort habe ich noch nie gehört.*"},{"label":"d","text":"Was bedeutet dieses Wort? → ___","gaps":[["1"]],"solution":"Was bedeutet dieses Wort? → **1**","en":"Que signifie ce mot ? → 1 Je ne sais malheureusement pas non plus.","why":"Une réponse à une question à laquelle on ne sait pas répondre."},{"label":"e","text":"Da habe ich echt Schwein gehabt. → ___","gaps":[["6"]],"solution":"Da habe ich echt Schwein gehabt. → **6**","en":"J'ai vraiment eu de la chance. → 6 Si j'ai bien compris, vous avez eu de la chance ?","why":"*Schwein haben* (familier) = avoir de la chance ; vous vérifiez que vous avez bien compris."},{"label":"f","text":"Könnten Sie bitte langsamer sprechen? → ___","gaps":[["3"]],"solution":"Könnten Sie bitte langsamer sprechen? → **3**","en":"Pourriez-vous parler plus lentement, s'il vous plaît ? → 3 D'accord, je vais essayer.","why":"Une réponse à une demande."}],"phrases":["1 Das weiss ich leider auch nicht.","2 Natürlich, gern.","3 Okay, ich versuche es.","4 Das Wort habe ich noch nie gehört.","5 Wie war bitte Ihr Name?","6 Habe ich das richtig verstanden: Du hattest Glück?"]},{"no":"8","instruction":"Schreiben Sie die Fragen.","instruction_en":"Écrivez les questions indirectes avec les mots entre parenthèses. Dans une question indirecte, le verbe va à la fin.","example":[{"label":"a","lead":"(Bild: Ein Mann und eine Frau lesen zusammen in einem Buch.) Weisst du vielleicht, … (Aufgabe – wie?)","text":"Weisst du vielleicht, **wie ich diese Aufgaben machen muss**?"}],"items":[{"label":"b","lead":"(Bild: Zwei Männer stehen mit ihren Mülltonnen auf der Strasse.) Können Sie mir sagen, … (Müll – wohin?)","text":"Können Sie mir sagen, ___?","gaps":[["wohin ich den Müll bringen muss","wohin ich den Müll bringen soll"]],"solution":"Können Sie mir sagen, **wohin ich den Müll bringen muss**?","en":"Pouvez-vous me dire où je dois apporter les ordures ?","why":"*wohin* introduit la question indirecte ; le verbe conjugué *muss* va à la fin."},{"label":"c","lead":"(Bild: Eine Frau sitzt beim Arzt.) Können Sie mir bitte sagen, … (Schmerzen – wo?)","text":"Können Sie mir bitte sagen, ___?","gaps":[["wo Sie Schmerzen haben"]],"solution":"Können Sie mir bitte sagen, **wo Sie Schmerzen haben**?","en":"Pouvez-vous me dire, s'il vous plaît, où vous avez mal ?","why":"Le médecin demande : *wo* + sujet + verbe à la fin (*haben*)."},{"label":"d","lead":"(Bild: Eine Frau fragt einen Mann im Zug.) Wissen Sie vielleicht, … (Zug nach Berlin – ob?)","text":"Wissen Sie vielleicht, ___?","gaps":[["ob der Zug nach Berlin fährt","ob dieser Zug nach Berlin fährt","ob das der Zug nach Berlin ist"]],"solution":"Wissen Sie vielleicht, **ob der Zug nach Berlin fährt**?","en":"Savez-vous par hasard si le train va à Berlin ?","why":"Une question fermée (oui/non) devient indirecte avec *ob* ; le verbe *fährt* va à la fin."}]}]},{"page":"Test L4 · 23","heading":"Schreiben","heading_en":"Expression écrite","exercises":[{"no":"9","instruction":"Wählen Sie eine Sprache, die Sie gern lernen würden, und schreiben Sie eine Nachricht an die Sprachschule. – Schreiben Sie, für welche Sprache Sie sich interessieren. – Sagen Sie, wann und wie oft pro Woche Sie Zeit für den Kurs haben. – Fragen Sie, zu welchen Terminen/Zeiten die Sprachschule einen Kurs in Ihrer Wunschsprache anbietet. – Fragen Sie auch nach den Kursgebühren und der Kursdauer. – Bitten Sie um eine Antwort. – Denken Sie an die passende Anrede und den Gruss am Ende.","instruction_en":"Choisissez une langue que vous aimeriez apprendre et écrivez un message à l'école de langues : quelle langue, quand et combien de fois par semaine vous avez du temps, quels jours et horaires de cours l'école propose, le prix et la durée du cours ; demandez une réponse et utilisez une formule d'appel et une formule de politesse adaptées. La réponse modèle suit le corrigé officiel.","phrases":["… Damen und Herren,","ich würde gern …","Ich … und …","Bitte teilen Sie mir mit, …","Auch müsste ich wissen, …","Mit …","**LERNTIPP** Was sagt man in dieser Situation? Notieren und lernen Sie nicht nur einzelne neue Wörter. Wenn Sie sich zu verschiedenen Situationen passende Sätze und Ausdrücke aufschreiben, fühlen Sie sich in Gesprächen sicherer. Benutzen Sie zum Beispiel Karteikärtchen und schreiben Sie eine Situation oder ein Thema auf die Vorderseite: «nachfragen». Schreiben Sie Beispiele zum Thema auf die Rückseite und lernen Sie diese auswendig: «Was meinen Sie mit …?», «Was bedeutet …?» … Diese Methode eignet sich auch gut, wenn Sie sich auf ein Gespräch vorbereiten möchten. Überlegen Sie, was Sie sagen oder fragen möchten und was der Gesprächspartner sagen oder fragen könnte. Sicher können Sie während des Gesprächs einen Ihrer geübten Sätze anwenden."],"items":[{"label":"9","text":"","open":true,"solution":"**Sehr geehrte** Damen und Herren, ich würde gern **Neugriechisch lernen**. Ich **habe von Montag bis Donnerstag abends Zeit** und **könnte zweimal pro Woche kommen**. Bitte teilen Sie mir mit, **zu welchen Zeiten Sie einen Neugriechisch-Kurs anbieten**. Auch müsste ich wissen, **wie viel der Kurs kostet und wie lange er dauert**. **Ich bitte Sie um eine kurze Antwort.** Mit **freundlichen Grüssen** …","en":"Madame, Monsieur, j'aimerais apprendre le grec moderne. J'ai du temps du lundi au jeudi le soir et je pourrais venir deux fois par semaine. Veuillez m'indiquer à quels horaires vous proposez un cours de grec moderne. J'aurais aussi besoin de savoir combien coûte le cours et combien de temps il dure. Je vous prie de me faire parvenir une courte réponse. Meilleures salutations …","why":"Lettre formelle : *Sehr geehrte Damen und Herren* … *Mit freundlichen Grüssen*. Les questions sont indirectes (*zu welchen Zeiten …, wie viel …, wie lange …*) : verbe à la fin."}]}]}]}];
